function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        return;
    }

    if (!/^\d{4}$/.test(newValue)) {
        g_form.addErrorMessage("Invalid format for Release Year");
        g_form.setValue("release_year", "");
    }
}
